        },
        "lkysfwkspz": {
            //公路、水路旅客运输服务等扣税凭证
            "je": "0.00",
            "se": "0.00"
        },
        "txfkspz": {
            //桥、闸通行费等扣税凭证
            "je": "0.00",
            "se": "0.00"
        },
        "ckhwznxzm": {
            //出口业务转内销证明

            "se": "0.00"
        },
        "zjgjsfzjgjxse": {
            //总机构接受分支机构进项税额

